<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Invoice extends Model {protected $guarded=[]; public function customer(){return $this->belongsTo(Customer::class);} public function job(){return $this->belongsTo(Job::class);} public function items(){return $this->hasMany(InvoiceItem::class);} public function payments(){return $this->hasMany(Payment::class);} }
